package dev.veltraph.client.garden.pests.tracker;

import dev.veltraph.client.world.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class PestRoofPlannerTest {
    private static final Vec3 FEET=new Vec3(.5,70,-96.5),EYE=new Vec3(.5,71.62,-96.5),LOOK=new Vec3(1,0,0);
    private static final BlockPos ROOF=new BlockPos(0,73,-97);
    private static final class World implements PestRoofPlanner.World {
        final Set<BlockPos> roofs=new HashSet<>(Set.of(ROOF)),obstructions=new HashSet<>(),unloaded=new HashSet<>(),noRay=new HashSet<>();
        final List<BlockPos> scanned=new ArrayList<>(),rays=new ArrayList<>();
        public boolean loaded(BlockPos p){return !unloaded.contains(p);}public boolean passable(BlockPos p){scanned.add(p);return !obstructions.contains(p);}
        public boolean validRoof(int plot,BlockPos p){return roofs.contains(p);}public Optional<PestRoofPlanner.Hop> ray(Vec3 eye,BlockPos p){rays.add(p);return noRay.contains(p)?Optional.empty():Optional.of(new PestRoofPlanner.Hop(p,Direction.DOWN,new Vec3(p.x()+.5,p.y()+1,p.z()+.5)));}
    }
    private PestRoofPlanner.Plan plan(PestRoofPlanner planner,World world){return planner.plan(world,1,FEET,EYE,LOOK,true,true,new Random(7));}
    @Test void sourceVerticalFallbackIsAnActualAcquiredHop(){var world=new World();var chosen=plan(new PestRoofPlanner(),world);assertEquals(PestRoofPlanner.Outcome.HOP,chosen.outcome());assertEquals(ROOF,chosen.hop().support());assertEquals(Direction.DOWN,chosen.hop().face());assertEquals(new Vec3(.5,74,-96.5),chosen.hop().landing());assertEquals(List.of(new BlockPos(0,70,-97),new BlockPos(0,71,-97),new BlockPos(0,72,-97)),world.scanned);assertEquals(List.of(ROOF),world.rays);}
    @Test void forwardJitterChoiceUsesOnlySixSourceDistancesAndExactRayWitnesses(){var world=new World();for(int x=9;x<=16;x++)for(int z=-98;z<=-96;z++)world.roofs.add(new BlockPos(x,73,z));var chosen=plan(new PestRoofPlanner(),world);assertEquals(PestRoofPlanner.Outcome.HOP,chosen.outcome());assertEquals(6,chosen.candidates().size());assertTrue(chosen.candidates().contains(chosen.hop().support()));for(int i=0;i<6;i++){var p=chosen.candidates().get(i);assertTrue(p.x()>=9+i&&p.x()<=11+i);assertTrue(p.z()>=-98&&p.z()<=-96);assertEquals(73,p.y());}assertEquals(chosen.candidates(),world.rays);}
    @Test void threeAttemptBudgetSurvivesAbsentRoofsAndNeverResetsAtNewPlot(){var world=new World();world.roofs.clear();var planner=new PestRoofPlanner();for(int i=1;i<=3;i++){var p=plan(planner,world);assertEquals(PestRoofPlanner.Outcome.NO_ROOF,p.outcome());assertEquals(i,p.attempt());}assertEquals(PestRoofPlanner.Outcome.EXHAUSTED,plan(planner,world).outcome());assertEquals(3,planner.attempts());planner.reset();assertEquals(1,plan(planner,world).attempt());}
    @Test void sourceY77IsExcludedEvenWhenItIsTheOnlyValidRoof(){var world=new World();world.roofs.clear();world.roofs.add(new BlockPos(0,77,-97));assertEquals(PestRoofPlanner.Outcome.NO_ROOF,plan(new PestRoofPlanner(),world).outcome());assertTrue(world.scanned.stream().allMatch(p->p.y()<77));assertTrue(world.rays.isEmpty());}
    @Test void obstructedOrUnloadedVerticalScanCannotAcquireADeeperRoof(){for(boolean unloaded:List.of(false,true)){var world=new World();var blocked=new BlockPos(0,71,-97);if(unloaded)world.unloaded.add(blocked);else world.obstructions.add(blocked);assertEquals(PestRoofPlanner.Outcome.BLOCKED,plan(new PestRoofPlanner(),world).outcome());assertTrue(world.rays.isEmpty());}}
    @Test void unreachableCandidateCannotBypassFallbackRay(){var world=new World();world.noRay.add(ROOF);assertEquals(PestRoofPlanner.Outcome.BLOCKED,plan(new PestRoofPlanner(),world).outcome());}
    @Test void noToolForeignPlotOrNonFiniteInputCannotConsumeAttemptOrDispatch(){var planner=new PestRoofPlanner();var world=new World();assertEquals(PestRoofPlanner.Outcome.REFUSED,planner.plan(world,1,FEET,EYE,LOOK,false,false,new Random(1)).outcome());assertEquals(PestRoofPlanner.Outcome.REFUSED,planner.plan(world,2,FEET,EYE,LOOK,true,false,new Random(1)).outcome());assertEquals(PestRoofPlanner.Outcome.REFUSED,planner.plan(world,1,FEET,EYE,new Vec3(Double.NaN,0,0),true,false,new Random(1)).outcome());assertEquals(0,planner.attempts());assertTrue(world.rays.isEmpty());}
    @Test void dispatchedSourceFlagRejectsNormalRepeatAndOnlyExplicitEvacuationOverrides(){var planner=new PestRoofPlanner();var world=new World();assertEquals(PestRoofPlanner.Outcome.HOP,plan(planner,world).outcome());planner.dispatched();assertEquals(PestRoofPlanner.Outcome.REFUSED,planner.plan(world,1,FEET,EYE,LOOK,true,false,new Random(1)).outcome());assertEquals(1,planner.attempts());assertEquals(PestRoofPlanner.Outcome.HOP,plan(planner,world).outcome());assertEquals(2,planner.attempts());}
    @Test void foreignLandingOrSupportCannotBeChosen(){var planner=new PestRoofPlanner();PestRoofPlanner.World world=new PestRoofPlanner.World(){public boolean loaded(BlockPos p){return true;}public boolean passable(BlockPos p){return true;}public boolean validRoof(int plot,BlockPos p){return p.equals(ROOF);}public Optional<PestRoofPlanner.Hop> ray(Vec3 eye,BlockPos p){return Optional.of(new PestRoofPlanner.Hop(p,Direction.DOWN,new Vec3(.5,74,.5)));}};assertEquals(PestRoofPlanner.Outcome.BLOCKED,planner.plan(world,1,FEET,EYE,LOOK,true,true,new Random(7)).outcome());}
    @Test void observedGeometryContractRejectsGuessedCoordinatesDuplicatesAndY77(){var support=new PestRoofBindings.Support(1,ROOF,"minecraft:stone");assertEquals(Optional.of(support),new PestRoofBindings(List.of(support)).at(1,ROOF));assertThrows(IllegalArgumentException.class,()->new PestRoofBindings(List.of(support,support)));assertThrows(IllegalArgumentException.class,()->new PestRoofBindings.Support(2,ROOF,"minecraft:stone"));assertThrows(IllegalArgumentException.class,()->new PestRoofBindings.Support(1,new BlockPos(0,77,-97),"minecraft:stone"));assertThrows(IllegalArgumentException.class,()->new PestRoofBindings(List.of()));}
}
